enum Kind  : unsigned char { kToggle, kChoice, kSlider, kAction, kInfo };
enum Field : unsigned char { fNone, fInt, fFloat, fStr, fPadBits, fPort };
enum Fmt   : unsigned char { fmtNone, fmtPct, fmtNum, fmtSec, fmtSigned };

struct Key    { const char* sec; const char* key; };
struct Choice { const char* ini; const char* ini2; const char* textKey; const char* en; const char* us; bool hidden; };
struct Section { const char* id; const char* textKey; const char* en; const char* helpKey; const char* help; };
struct Item
{
    const char* id; int section;          // -1 = the root page
    Kind kind; Field field;
    unsigned cfgOff; unsigned short cfgSize;     // [11-24] offset is 32-bit: Config grew past 64 KB (spots data) and 16 bits wrapped;
    unsigned ini2Off;                   //
    Key key; Key also[2];               // also: written with the same value (a choice's ini2 for also[0])
    float lo, hi, step; Fmt fmt;
    const char* def;                    // the shipped value, as lcudrive.ini spells it
    const Choice* choices; int nChoices;
    const char* labelKey; const char* label; const char* labelUs;
    const char* helpKey;  const char* help;  const char* helpUs;
    const char* request;                // actions / info: what the menu posts or reads (see menu_bridge.h)
    const char* confirm;                // actions: a confirm prompt's text key, or nullptr
    bool v1Hidden;                      // in the table, not on the v1 page (see menu_spec.py)
};

